#pragma once
#include "contour.hpp"
inline Pair interpolated(const Pair& p){Pair out;out.mask=p.mask;auto has=[&](int x,int y){return x>=0&&y>=0&&x<p.mask.cols&&y<p.mask.rows&&p.mask.at<uint8_t>(y,x)>0;};for(int y=-1;y<p.mask.rows;++y)for(int x=-1;x<p.mask.cols;++x){int code=has(x,y)+2*has(x+1,y)+4*has(x+1,y+1)+8*has(x,y+1);std::array<V2,4> u={V2(x+.5,y),V2(x+1,y+.5),V2(x+.5,y+1),V2(x,y+.5)};auto add=[&](int a,int b){out.contour.push_back({u[a].x(),u[a].y(),u[b].x(),u[b].y()});};switch(code){case 1:add(3,0);break;case 2:add(0,1);break;case 3:add(3,1);break;case 4:add(1,2);break;case 5:add(3,0);add(1,2);break;case 6:add(0,2);break;case 7:add(3,2);break;case 8:add(2,3);break;case 9:add(0,2);break;case 10:add(0,1);add(2,3);break;case 11:add(1,2);break;case 12:add(1,3);break;case 13:add(0,1);break;case 14:add(0,3);break;default:break;}}return out;}
inline bool polygon_inside(const Pair&p,V2 u){bool in=false;for(auto s:p.contour){if((s[1]>u.y())!=(s[3]>u.y())){double x=s[0]+(u.y()-s[1])*(s[2]-s[0])/(s[3]-s[1]);if(u.x()<x)in=!in;}}return in;}
inline double exterior_distance(const Pair&p,V2 u){return polygon_inside(p,u)?0:std::sqrt(std::expm1(contour_cost(p,u).first));}
inline void prepare_interpolated_region(Pair&p){auto raw=interpolated(p);std::map<std::pair<int,int>,std::vector<std::pair<int,int>>> lines;for(auto s:raw.contour){int x0=std::lround(2*s[0]),y0=std::lround(2*s[1]),x1=std::lround(2*s[2]),y1=std::lround(2*s[3]),kind,key,a,b;if(y0==y1){kind=0;key=y0;a=x0;b=x1;}else if(x0==x1){kind=1;key=x0;a=y0;b=y1;}else{kind=(x1-x0)*(y1-y0)>0?2:3;key=kind==2?y0-x0:y0+x0;a=x0;b=x1;}if(a>b)std::swap(a,b);lines[{kind,key}].push_back({a,b});}p.region_edges.clear();for(auto&item:lines){auto&v=item.second;std::sort(v.begin(),v.end());int kind=item.first.first,key=item.first.second;auto add=[&](int a,int b){if(kind==0)p.region_edges.push_back({a*.5,key*.5,b*.5,key*.5});else if(kind==1)p.region_edges.push_back({key*.5,a*.5,key*.5,b*.5});else if(kind==2)p.region_edges.push_back({a*.5,(a+key)*.5,b*.5,(b+key)*.5});else p.region_edges.push_back({a*.5,(key-a)*.5,b*.5,(key-b)*.5});};int a=v[0].first,b=v[0].second;for(size_t i=1;i<v.size();++i){if(v[i].first<=b)b=std::max(b,v[i].second);else{add(a,b);a=v[i].first;b=v[i].second;}}add(a,b);}if(p.region_edges.empty())throw std::runtime_error("empty interpolated region");}
inline bool region_inside(const Pair&p,V2 u){bool in=false;for(auto s:p.region_edges)if((s[1]>u.y())!=(s[3]>u.y())&&u.x()<s[0]+(u.y()-s[1])*(s[2]-s[0])/(s[3]-s[1]))in=!in;return in;}
inline std::pair<double,V2> region_cost(const Pair&p,V2 u){double best=INFINITY;V2 r=V2::Zero();for(auto s:p.region_edges){V2 a(s[0],s[1]),v(s[2]-s[0],s[3]-s[1]);V2 e=u-a-std::clamp((u-a).dot(v)/v.squaredNorm(),0.,1.)*v;if(e.squaredNorm()<best){best=e.squaredNorm();r=e;}}return {std::log1p(best),2*r/(1+best)};}
inline std::pair<double,V2> interpolated_gate(const Pair&p,V2 u){if(region_inside(p,u))return {0,V2::Zero()};auto c=region_cost(p,u);return {-std::expm1(-c.first),std::exp(-c.first)*c.second};}
